<script setup lang="ts">
import { useRoute,useRouter } from 'vue-router'
import { ref } from 'vue'
import { ArrowPathIcon } from '@heroicons/vue/24/outline'
import PageHeading from '../components/PageHeading.vue'
import { useInvestigation,queryString,date } from '../composables/investigation'
import type { DeliveryHistoryResult } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<DeliveryHistoryResult>(()=>'/deliveries?'+queryString(route.query)),environment=ref(String(route.query.environment??'')),issue=ref(String(route.query.issue??'')),rule=ref(String(route.query.rule??''))
function set(key:string,value:string){router.replace({query:{...route.query,page:undefined,[key]:value||undefined}})}
function apply(){router.replace({query:{...route.query,environment:environment.value||undefined,issue:issue.value||undefined,rule:rule.value||undefined,page:undefined}})}
</script>
<template><PageHeading title="Delivery history" subtitle="Durable notification intent, attempts and recovery."><RouterLink to="/alerts" class="button">Alert rules</RouterLink><button class="button icon-button" aria-label="Refresh deliveries" :disabled="loading" @click="reload"><ArrowPathIcon/></button></PageHeading><div class="delivery-filters"><label>Status<select :value="route.query.status??''" @change="set('status',($event.target as HTMLSelectElement).value)"><option value="">All statuses</option><option v-for="s in ['pending','processing','retrying','sent','cancelled','failed','needs_review']" :key="s">{{s}}</option></select></label><label>Type<select :value="route.query.test??''" @change="set('test',($event.target as HTMLSelectElement).value)"><option value="">Tests and real events</option><option value="1">Synthetic tests</option><option value="0">Automatic events</option></select></label><label>Channel<select aria-label="Delivery channel"><option>Email</option></select></label><details><summary>More filters</summary><form @submit.prevent="apply"><label class="field">Environment<input v-model="environment"></label><label class="field">Error UUID<input v-model="issue"></label><label class="field">Rule UUID<input v-model="rule"></label><label class="field">Created after (UTC)<input type="date" :value="route.query.after" @change="set('after',($event.target as HTMLInputElement).value)"></label><label class="field">Created before (UTC)<input type="date" :value="route.query.before" @change="set('before',($event.target as HTMLInputElement).value)"></label><button class="button">Apply delivery filters</button></form></details></div><div v-if="error" class="notice danger" role="alert">{{error}}<button class="button" @click="reload">Try again</button><RouterLink to="/alerts/history" class="text-link">Clear filters</RouterLink></div><p v-if="loading" role="status">Loading delivery history…</p><template v-if="data"><p class="notice neutral">{{data.acceptance_note}}</p><div class="table-scroll delivery-table" tabindex="0" role="region" aria-label="Delivery history, scroll for more columns"><table><thead><tr><th>Event</th><th>Recipient</th><th>Status</th><th>Attempts</th><th>Next eligible / completed</th></tr></thead><tbody><tr v-for="d in data.items" :key="d.id"><td><RouterLink :to="'/alerts/history/'+d.id">{{d.action==='connection_test'?'Synthetic test':d.event}}</RouterLink><small>{{d.environment}} · {{date(d.created_at)}}</small></td><td>{{d.destination_name}}<small>{{d.destination}}</small></td><td><span class="status-badge" :class="'status-'+d.status">{{d.status}}</span><small>{{d.reason}}</small></td><td>{{d.attempts}} <small>cycle {{d.cycle}}</small></td><td>{{date(d.completed_at??d.eligible_at)}}</td></tr><tr v-if="!data.items.length"><td colspan="5" class="table-empty">No deliveries match these filters. <RouterLink to="/alerts/history" class="text-link">Clear filters</RouterLink></td></tr></tbody></table></div><div class="pagination"><span>{{data.total}} deliveries · page {{data.page}} of {{data.last_page}}</span><button class="button" :disabled="data.page<=1" @click="set('page',String(data.page-1))">Previous deliveries</button><button class="button" :disabled="data.page>=data.last_page" @click="set('page',String(data.page+1))">Next deliveries</button></div><p class="data-caption">Data as of {{date(data.as_of)}}</p></template></template>
